package local.pocketchat;import android.content.Context;import android.net.Uri;import java.io.*;import java.util.*;import org.json.*;
final class Profiles {static Context global(Context c){return new Context(c.root,0);}static int slot(Context c){return c.slot;}}
final class FileDownloads {static String safeName(String name){return name;}}
final class Attachments {static String sizeLabel(long bytes){return bytes+" B";}}
final class AppUpdatePolicy {static String hash(byte[] raw){try{byte[] hash=java.security.MessageDigest.getInstance("SHA-256").digest(raw);StringBuilder out=new StringBuilder();for(byte b:hash)out.append(String.format("%02x",b));return out.toString();}catch(Exception e){throw new IllegalStateException(e);}}}
final class SavedDownloadProvider {static File resolve(Context c,Uri uri){List<String> p=uri.getPathSegments();return new File(new Context(c.root,Integer.parseInt(p.get(0))).getFilesDir(),"saved-downloads/"+p.get(1)+"/"+p.get(2));}}
/** Deliberately a memory index double; SQLite behavior is covered by Android integration, not this host suite. */
final class DownloadLibrary {static final Map<String,DownloadLibrary> all=new HashMap<>();static synchronized DownloadLibrary get(Context c){return all.computeIfAbsent(c.root.toString(),x->new DownloadLibrary());}volatile boolean failNextSync;final Map<String,JSONObject> saved=new HashMap<>();final Set<String> deleted=new HashSet<>();synchronized boolean isRemoved(JSONObject row){return deleted.contains(row.optString("uri"));}synchronized JSONArray prune(JSONArray rows){JSONArray out=new JSONArray();for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);if(r!=null&&!isRemoved(r))out.put(r);}return out;}synchronized void add(Context c,JSONObject row){if(!isRemoved(row))saved.put(row.optString("uri"),J.parse(row.toString()));}void sync(Context c,JSONArray rows){if(failNextSync){failNextSync=false;throw new IllegalStateException("Injected index failure after task commit");}}synchronized boolean indexed(Uri uri){return saved.containsKey(uri.toString());}synchronized JSONObject saved(JSONObject row){JSONObject current=saved.get(row.optString("uri"));return current!=null&&current.optString("id").equals(row.optString("id"))?current:null;}synchronized void removeSaved(JSONObject row){saved.remove(row.optString("uri"));deleted.add(row.optString("uri"));}}
